<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../../services/api';import PageHeader from'../../components/PageHeader.vue';const circles=ref<any[]>([]);const search=ref('');const invite=ref('');const notice=ref('');onMounted(async()=>{try{circles.value=(await api.get('/circles')).data;}catch{circles.value=[{id:'demo',name:'主播生活圈',description:'直播预告、专属动态与幕后素材',entryCoins:99}];}});function bind(){notice.value=invite.value.length>=6?'邀请码已提交':'请输入有效邀请码';}</script><template><main class="page business-page"><PageHeader title="主播圈子" subtitle="加入喜欢的主播社区"/><div class="search-box"><span>⌕</span><input v-model="search" aria-label="搜索圈子" placeholder="搜索圈子或主播"></div><section class="invite-card"><div><b>使用邀请码加入</b><small>输入主播分享的邀请码</small></div><div><input v-model="invite" aria-label="圈子邀请码" maxlength="12" placeholder="邀请码"><button @click="bind">绑定</button></div><p v-if="notice">{{notice}}</p></section><h2 class="block-title">可加入圈子</h2><article v-for="circle in circles.filter(c=>c.name.includes(search))" :key="circle.id" class="circle-card"><div class="circle-cover">圈</div><div><h3>{{circle.name}}</h3><p>{{circle.description}}</p><span>◈ {{circle.entryCoins}} 金币</span></div><button>查看</button></article></main></template>
